function pinOf(c){const m=c&&c.pin?/^([uo])([0-9]\.5)$/.exec(c.pin):null;if(!m)return null;const side=m[1]==='o'?'over':'under',line=parseFloat(m[2]);return mkValid(side,line)?{side:side,line:line}:null}
