const VERSION=1;
const API='https://v3.football.api-sports.io';
const PLAYING=['1H','2H','ET','LIVE'];   // not HT, suspended, interrupted or finished
const MAX_STATS=12;                      // statistics lookups per run
const BUDGET=30;                         // API calls per run (the free Workers plan allows 50 outside calls in all, KV and push included)
const MAX_ALERTS=5;                      // alerts per run; any others go out the next minute
const SENT_KEEP=3*3600*1000;             // one alert per match; remembered for 3 hours
const TTL=180;                           // seconds the phone's push service keeps an undelivered alert
const PUSH_HOSTS=['.push.apple.com','fcm.googleapis.com','.push.services.mozilla.com','.notify.windows.com'];
const CORS={'access-control-allow-origin':'*','access-control-allow-headers':'authorization,content-type','access-control-allow-methods':'GET,POST,OPTIONS','access-control-max-age':'86400'};

// ---------- small helpers
const enc=s=>new TextEncoder().encode(s);
const cat=(...a)=>{const n=a.reduce((t,x)=>t+x.length,0),o=new Uint8Array(n);let i=0;a.forEach(x=>{o.set(x,i);i+=x.length});return o};
const b64u=u=>{let s='';for(let i=0;i<u.length;i++)s+=String.fromCharCode(u[i]);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
const unb64u=t=>{let s=String(t).replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u};
const json=(o,st)=>new Response(JSON.stringify(o),{status:st||200,headers:Object.assign({'content-type':'application/json'},CORS)});
async function kget(env,k,opt){try{const t=await env.STORE.get(k,opt);return t?JSON.parse(t):null}catch(e){return null}}
const kput=(env,k,v)=>env.STORE.put(k,JSON.stringify(v));
function same(a,b){a=String(a);b=String(b);let d=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)d|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return d===0}

// ---------- Web Push: message encryption (RFC 8291, aes128gcm) and VAPID (RFC 8292)
async function hkdf(salt,ikm,info,len){
  const k=await crypto.subtle.importKey('raw',ikm,'HKDF',false,['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt:salt,info:info},k,len*8));
}
// sub: {endpoint, keys:{p256dh, auth}}; data: Uint8Array. o.salt / o.asPriv / o.asPub are for tests only.
async function encryptPush(sub,data,o){
  o=o||{};
  const ua=unb64u(sub.keys.p256dh),auth=unb64u(sub.keys.auth);
  const salt=o.salt||crypto.getRandomValues(new Uint8Array(16));
  const alg={name:'ECDH',namedCurve:'P-256'};
  let priv,pub;
  if(o.asPriv){
    pub=o.asPub;
    priv=await crypto.subtle.importKey('jwk',{kty:'EC',crv:'P-256',d:b64u(o.asPriv),x:b64u(pub.slice(1,33)),y:b64u(pub.slice(33,65))},alg,false,['deriveBits']);
  }else{
    const kp=await crypto.subtle.generateKey(alg,true,['deriveBits']);
    priv=kp.privateKey;pub=new Uint8Array(await crypto.subtle.exportKey('raw',kp.publicKey));
  }
  const uaKey=await crypto.subtle.importKey('raw',ua,alg,false,[]);
  const shared=new Uint8Array(await crypto.subtle.deriveBits({name:'ECDH',public:uaKey},priv,256));
  const ikm=await hkdf(auth,shared,cat(enc('WebPush: info\0'),ua,pub),32);
  const cek=await hkdf(salt,ikm,enc('Content-Encoding: aes128gcm\0'),16);
  const nonce=await hkdf(salt,ikm,enc('Content-Encoding: nonce\0'),12);
  if(data.length>4000)throw new Error('message too long');
  const key=await crypto.subtle.importKey('raw',cek,'AES-GCM',false,['encrypt']);
  const ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv:nonce},key,cat(data,new Uint8Array([2]))));
  return cat(salt,new Uint8Array([0,0,16,0]),new Uint8Array([pub.length]),pub,ct);   // record size 4096
}
async function vapidAuth(endpoint,vapid,subject,now){
  const hdr=b64u(enc(JSON.stringify({typ:'JWT',alg:'ES256'})));
  const pl=b64u(enc(JSON.stringify({aud:new URL(endpoint).origin,exp:Math.floor(now/1000)+12*3600,sub:subject})));
  const key=await crypto.subtle.importKey('jwk',vapid.jwk,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
  const sig=new Uint8Array(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,enc(hdr+'.'+pl)));   // r||s, 64 bytes
  return 'vapid t='+hdr+'.'+pl+'.'+b64u(sig)+', k='+vapid.pub;
}
async function sendPush(sub,msg,vapid,subject,now){
  const body=await encryptPush(sub,enc(JSON.stringify(msg)));
  const r=await fetch(sub.endpoint,{method:'POST',headers:{authorization:await vapidAuth(sub.endpoint,vapid,subject,now),'content-encoding':'aes128gcm','content-type':'application/octet-stream',ttl:String(TTL),urgency:'high'},body:body});
  return r.status;
}
async function getVapid(env){
  let v=await kget(env,'vapid');
  if(v&&v.pub&&v.jwk)return v;
  const kp=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);
  const j=await crypto.subtle.exportKey('jwk',kp.privateKey);
  v={pub:b64u(new Uint8Array(await crypto.subtle.exportKey('raw',kp.publicKey))),jwk:{kty:j.kty,crv:j.crv,x:j.x,y:j.y,d:j.d}};
  await kput(env,'vapid',v);
  return v;
}
// The phones and keys, read once per run.
async function pushCtx(env){
  const subs=(await kget(env,'subs'))||[];
  if(!subs.length)return{subs:subs};
  const vapid=await getVapid(env),meta=(await kget(env,'meta'))||{};
  return{subs:subs,vapid:vapid,subject:meta.origin||'mailto:alerts@example.com'};
}
// Sends one message to every phone. A phone the push service says is gone (404/410) is listed in gone.
async function pushTo(px,msg,now){
  const res=await Promise.all(px.subs.map(async s=>{try{return{ep:s.endpoint,code:await sendPush(s,msg,px.vapid,px.subject,now)}}catch(e){return{ep:s.endpoint,code:0,err:String(e&&e.message||e).slice(0,120)}}}));
  return{n:res.length,ok:res.filter(r=>r.code>=200&&r.code<300).length,codes:res.map(r=>r.code||r.err||0),gone:res.filter(r=>r.code===404||r.code===410).map(r=>r.ep)};
}
async function dropGone(env,gone){
  if(!gone.length)return;
  const cur=(await kget(env,'subs'))||[];
  await kput(env,'subs',cur.filter(s=>gone.indexOf(s.endpoint)<0));
}
async function pushAll(env,msg,now){
  const px=await pushCtx(env);
  if(!px.subs.length)return{n:0,ok:0,codes:[],gone:[]};
  const r=await pushTo(px,msg,now);
  await dropGone(env,r.gone);
  return r;
}

// ---------- the check that runs every minute
const mem=new Map();   // fixtures alerted by this running copy of the Worker (guards against a slow KV read)
function pruneSent(sent,now){const o={};Object.keys(sent||{}).forEach(k=>{if(now-sent[k].at<SENT_KEEP)o[k]=sent[k]});return o}
async function check(env,o){
  o=o||{};
  const now=o.now||Date.now();
  const rec=await kget(env,'cfg'),subs=(await kget(env,'subs'))||[];
  if(!rec||!rec.key||!rec.cfg)return{ran:false,why:'not set up'};
  if(!subs.length)return{ran:false,why:'no phone turned on'};
  const hold=rec.mute||{};
  if(hold.off||hold.until>now)return{ran:false,why:'muted'+(hold.why?': '+hold.why:'')};
  const st=(await kget(env,'stat'))||{},today=new Date(now).toISOString().slice(0,10);
  const remKnown=st.remDay===today&&st.rem!=null;
  let every=st.mode==='idle'?4:st.mode==='warm'?2:1;
  if(remKnown&&st.rem<400)every=Math.max(every,5);
  if(remKnown&&st.rem<40)return{ran:false,why:'daily request limit almost used'};
  if(!o.force&&Math.floor(now/60000)%every)return{ran:false,why:'resting'};

  const c=Object.assign({},L.D,rec.cfg),out={ran:true,hits:[],err:'',calls:0};
  let rem=null,lim=null;
  const get=async path=>{
    if(out.calls>=BUDGET)throw new Error('call budget used');
    out.calls++;
    const r=await fetch(API+path,{headers:{'x-apisports-key':rec.key}});
    const a=r.headers.get('x-ratelimit-requests-remaining'),b=r.headers.get('x-ratelimit-requests-limit');
    if(a!=null&&isFinite(+a))rem=+a;
    if(b!=null&&isFinite(+b))lim=+b;
    if(r.status===401||r.status===403)throw new Error('The API rejected your key.');
    if(r.status===429)throw new Error('Too many requests.');
    if(!r.ok)throw new Error('The API answered '+r.status+'.');
    const j=await r.json(),em=L.apiErr(j);
    if(em)throw new Error(em);
    return j;
  };
  let list=[];
  try{list=L.apiLive(await get('/fixtures?live=all'))}catch(e){out.err=e.message}
  const play=list.filter(f=>PLAYING.indexOf(f.short)>=0&&!L.apiDone(f));
  const lo=c.minFrom,hi=c.minTo;
  const inWin=play.filter(f=>f.min>=lo&&f.min<=hi);
  out.mode=out.err?(st.mode||'hot'):play.some(f=>f.min>=lo-4&&f.min<=hi)?'hot':play.some(f=>f.min>=lo-14&&f.min<lo-4)?'warm':'idle';
  out.live=list.length;out.inWin=inWin.length;

  if(!out.err&&inWin.length){
    let sent=pruneSent(await kget(env,'sent',{cacheTtl:30}),now);
    const cand=inWin.filter(f=>!sent[f.id]&&!mem.has(f.id)&&L.scanClassAll(f,null,null,c).k!=='out').slice(0,MAX_STATS);
    out.scanned=cand.length;
    const needAvg=c.basis!=='live';
    let avg=needAvg?((await kget(env,'avg'))||{}):null,avgNew=false;
    const getAvg=async id=>{
      const k=today+':'+id;
      if(avg[k]!==undefined)return avg[k];
      const v=L.apiAvg(await get('/fixtures?team='+encodeURIComponent(id)+'&last=5'),id);
      avg[k]=v;avgNew=true;return v;
    };
    const one=async f=>{
      try{
        const r=await Promise.all([get('/fixtures/statistics?fixture='+encodeURIComponent(f.id)),needAvg?getAvg(f.home.id):null,needAvg?getAvg(f.away.id):null]);
        const stt=L.apiStats(r[0],f.home.id,f.away.id),x=L.scanClassAll(f,stt,{h:r[1],a:r[2]},c);
        if(x.k==='go')out.hits.push({f:f,x:x,st:stt});
      }catch(e){out.err=out.err||e.message}
    };
    for(let i=0;i<cand.length;i+=3){
      if(out.calls>=BUDGET-3)break;
      await Promise.all(cand.slice(i,i+3).map(one));
    }
    if(avgNew){
      const keep={};Object.keys(avg).forEach(k=>{if(k.indexOf(today+':')===0)keep[k]=avg[k]});
      try{await kput(env,'avg',keep)}catch(e){}
    }
    // Alerts must go out even if Cloudflare refuses a save (for example the daily save allowance is used up).
    const save=async(k,v)=>{try{await kput(env,k,v)}catch(e){out.err=out.err||'Cloudflare refused a save: '+String(e&&e.message||e).slice(0,80)}};
    const hits=out.hits.slice(0,MAX_ALERTS);
    if(hits.length){
      const px=await pushCtx(env);
      hits.forEach(h=>{
        const f=h.f,pin=L.pinOf(c),mk=h.x.mk||L.mkName(pin?pin.side:c.side,pin?pin.line:L.lineOf(c));
        const sot=h.st&&h.st.sotH!=null&&h.st.sotA!=null?' · shots on target '+h.st.sotH+'–'+h.st.sotA:'';
        h.msg={t:'BET '+mk.toUpperCase(),b:f.home.name+' v '+f.away.name+' · '+f.min+"' · "+(f.gh==null?'-':f.gh)+'–'+(f.ga==null?'-':f.ga)+sot,g:'fx'+f.id,u:'./',x:now};
        // Remember it before sending, so the next run does not send it twice; forgotten again below if no phone took it.
        mem.set(f.id,now);sent[f.id]={at:now,mk:mk};
      });
      await save('sent',sent);
      const gone=[];
      await Promise.all(hits.map(async h=>{h.push=px.subs.length?await pushTo(px,h.msg,now):{n:0,ok:0,codes:[],gone:[]};h.push.gone.forEach(g=>{if(gone.indexOf(g)<0)gone.push(g)})}));
      const failed=hits.filter(h=>!h.push.ok);
      if(failed.length){
        failed.forEach(h=>{mem.delete(h.f.id);delete sent[h.f.id]});
        await save('sent',sent);
        out.err=out.err||'No phone took the alert ('+failed[0].push.codes.join(', ')+').';
      }
      try{await dropGone(env,gone)}catch(e){}
      out.hits=hits;
    }
    if(mem.size>200)mem.clear();
  }

  // Keep the status note fresh without spending KV writes every minute (the free plan allows 1,000 a day).
  const sentNow=out.hits.filter(h=>h.push&&h.push.ok);
  const last=sentNow.length?{at:now,t:sentNow[sentNow.length-1].msg.t,b:sentNow[sentNow.length-1].msg.b}:st.last;
  const nst={at:now,mode:out.mode,live:out.live,inWin:out.inWin,scanned:out.scanned||0,rem:rem!=null?rem:st.remDay===today?st.rem:null,lim:lim!=null?lim:st.lim,remDay:rem!=null?today:st.remDay,err:out.err,last:last,total:(st.total||0)+sentNow.length};
  if(sentNow.length||nst.mode!==st.mode||nst.err!==(st.err||'')||now-(st.at||0)>15*60000){try{await kput(env,'stat',nst)}catch(e){}}
  out.rem=nst.rem;
  return out;
}
async function noteErr(env,e){
  try{const st=(await kget(env,'stat'))||{},m=String(e&&e.message||e).slice(0,160);if(st.err!==m){st.err=m;st.at=Date.now();await kput(env,'stat',st)}}catch(_){}
}

// ---------- the endpoints your phone talks to
async function handle(req,env){
  const url=new URL(req.url),p=url.pathname.replace(/\/+$/,'')||'/';
  if(req.method==='OPTIONS')return new Response(null,{status:204,headers:CORS});
  if(p==='/'||p==='/ping')return json({ok:true,name:'sporthub-alerts',v:VERSION,password:!!env.TOKEN,kv:!!env.STORE});
  if(!env.TOKEN)return json({error:'Set the TOKEN variable on the Worker first.'},503);
  if(!env.STORE)return json({error:'Bind a KV namespace named STORE to the Worker first.'},503);
  const auth=req.headers.get('authorization')||'';
  if(!same(auth,'Bearer '+env.TOKEN))return json({error:'Wrong password.'},401);
  const now=Date.now();
  let body={};
  if(req.method==='POST'){
    const t=await req.text();
    if(t.length>60000)return json({error:'Too much data.'},413);
    try{body=t?JSON.parse(t):{}}catch(e){return json({error:'Could not read that.'},400)}
  }
  if(p==='/key'&&req.method==='GET')return json({key:(await getVapid(env)).pub});
  if(p==='/subscribe'&&req.method==='POST'){
    const s=body.sub;let host='';
    try{host=new URL(s.endpoint).hostname}catch(e){}
    if(!s||!s.keys||!s.keys.p256dh||!s.keys.auth||!host||new URL(s.endpoint).protocol!=='https:'||!PUSH_HOSTS.some(h=>h[0]==='.'?host.endsWith(h):host===h))return json({error:'That phone subscription was not accepted.'},400);
    const sub={endpoint:s.endpoint,keys:{p256dh:s.keys.p256dh,auth:s.keys.auth}};
    let subs=(await kget(env,'subs'))||[];
    const i=subs.findIndex(x=>x.endpoint===sub.endpoint);
    if(i<0||subs[i].keys.p256dh!==sub.keys.p256dh||subs[i].keys.auth!==sub.keys.auth){
      if(i>=0)subs[i]=sub;else subs=subs.concat([sub]).slice(-5);
      await kput(env,'subs',subs);
    }
    const meta=(await kget(env,'meta'))||{};
    if(meta.origin!==url.origin){meta.origin=url.origin;await kput(env,'meta',meta)}
    return json({ok:true,phones:subs.length});
  }
  if(p==='/unsubscribe'&&req.method==='POST'){
    const subs=((await kget(env,'subs'))||[]).filter(x=>x.endpoint!==body.endpoint);
    await kput(env,'subs',subs);
    if(!subs.length)await env.STORE.delete('cfg');   // nothing left to alert: forget the API key too
    return json({ok:true,phones:subs.length});
  }
  if(p==='/sync'&&req.method==='POST'){
    const k=String(body.key||''),cfg=body.cfg,m=body.mute||{};
    if(!/^[A-Za-z0-9_-]{8,100}$/.test(k))return json({error:'The API-Sports key looks wrong. Check it in Settings.'},400);
    if(!cfg||typeof cfg!=='object'||Array.isArray(cfg)||JSON.stringify(cfg).length>30000)return json({error:'The settings were not accepted.'},400);
    const mute={off:!!m.off,until:isFinite(+m.until)?+m.until:0,why:String(m.why||'').slice(0,100)};
    await kput(env,'cfg',{cfg:cfg,key:k,mute:mute,at:now});
    return json({ok:true,at:now});
  }
  if(p==='/test'&&req.method==='POST'){
    const r=await pushAll(env,{t:'SPORTHUB alerts are on',b:"This is a test. A real alert reads like: BET UNDER 3.5 · Arsenal v Chelsea · 62' · 1–0",g:'test',u:'./',x:now},now);
    if(!r.n)return json({error:'No phone is turned on yet.'},409);
    return json({ok:r.ok>0,sent:r.ok,phones:r.n,codes:r.codes});
  }
  if(p==='/status'&&req.method==='GET'){
    const rec=await kget(env,'cfg'),subs=(await kget(env,'subs'))||[],st=(await kget(env,'stat'))||{};
    return json({ok:true,v:VERSION,phones:subs.length,key:!!(rec&&rec.key),settingsAt:rec?rec.at:0,hold:rec?rec.mute:null,stat:st,now:now});
  }
  return json({error:'Not found.'},404);
}
export default{
  async fetch(req,env){try{return await handle(req,env)}catch(e){return json({error:String(e&&e.message||e).slice(0,160)},500)}},
  async scheduled(ev,env,ctx){ctx.waitUntil(check(env,{now:ev.scheduledTime||Date.now()}).catch(e=>noteErr(env,e)))}
};
